  /// <summary>How many requests the channel starts in a window of time.</summary>
  /// <remarks>Defaults to <c>{}</c>, which sets none: requests start as they are made.</remarks>
  [JsonPropertyName("Limit")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public RateLimitOptions? Limit { get; set; }

  /// <summary>Refuses an option outside the range the engine accepts.</summary>
  /// <exception cref="ArgumentOutOfRangeException">An option is outside its stated bounds.</exception>
  public void Validate()
  {
    Limit?.Validate();
  }
}

/// <summary>How many requests a channel starts in a window of time.</summary>
/// <remarks>
///   Off unless both options are set, or when <c>Calls</c> is 0. A request is an attempt, the first of a call or a retry of it,
///   because the server sees each as a request; a streaming call counts once, when it starts. The
///   first request opens a window of <c>PerSeconds</c>, and <c>Calls</c> of them start in it; the first request
///   after the window ends opens the next. Windows are fixed, so up to twice <c>Calls</c> requests can
///   start within <c>PerSeconds</c> across a boundary, the last of one window and the first of the next.
///   A call's first attempt over the limit waits for the next window and is not refused: a call whose
///   deadline passes while it waits ends <c>DEADLINE_EXCEEDED</c>, and one cancelled ends <c>CANCELLED</c>,
///   neither having sent anything. Requests start in the order they reach the limit, and the limit
///   is the channel's, shared by every connection it opens. A retry the retry policy chooses does
///   not wait: once its backoff has passed it takes a turn only if one is free, and otherwise it is
///   skipped. A skipped retry counts as an attempt, and the call goes on to its next backoff; when
///   the attempts are spent the call ends with the status of the last attempt sent. A resend of a
///   request its peer never processed is no retry of the policy's, and waits its turn like a first
///   attempt.
/// </remarks>
public sealed class RateLimitOptions
{
  /// <summary>Options nobody has set.</summary>
  public RateLimitOptions()
  {
  }

  /// <summary>A copy of <paramref name="other" />, sharing nothing with it.</summary>
  /// <param name="other">The options to copy.</param>
  /// <exception cref="ArgumentNullException"><paramref name="other" /> is null.</exception>
  public RateLimitOptions(RateLimitOptions other)
  {
    if (other is null)
    {
      throw new ArgumentNullException(nameof(other));
    }

    Calls = other.Calls;
    PerSeconds = other.PerSeconds;
  }

  /// <summary>The requests that start in one window, or 0 for no limit, over one an earlier source set.</summary>
  /// <remarks>Incoherent without <c>PerSeconds</c>, unless it is 0, which leaves <c>PerSeconds</c> unread.</remarks>
  [JsonPropertyName("Calls")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public int? Calls { get; set; }

  /// <summary>How long a window lasts.</summary>
  /// <remarks>Incoherent without <c>Calls</c>, unless <c>Calls</c> is 0.</remarks>
  [JsonPropertyName("PerSeconds")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public double? PerSeconds { get; set; }

  /// <summary>Refuses an option outside the range the engine accepts.</summary>
  /// <exception cref="ArgumentOutOfRangeException">An option is outside its stated bounds.</exception>
  public void Validate()
  {
    if (Calls is int calls && calls < 0)
    {
      throw new ArgumentOutOfRangeException(nameof(Calls),
                                            calls,
                                            "Calls has to be at least 0.");
    }

    if (PerSeconds is double perSeconds && (perSeconds < 1E-09 || perSeconds >= 1.8446744073709552E+19 || double.IsNaN(perSeconds) || double.IsInfinity(perSeconds)))
    {
      throw new ArgumentOutOfRangeException(nameof(PerSeconds),
                                            perSeconds,
                                            "PerSeconds has to be at least 1E-09 and less than 1.8446744073709552E+19 and finite.");
    }
  }
}

/// <summary>What a call sends to the server.</summary>
public sealed class GrpcSendOptions
{
  /// <summary>Options nobody has set.</summary>
  public GrpcSendOptions()
  {
  }

  /// <summary>A copy of <paramref name="other" />, sharing nothing with it.</summary>
  /// <param name="other">The options to copy.</param>
  /// <exception cref="ArgumentNullException"><paramref name="other" /> is null.</exception>
  public GrpcSendOptions(GrpcSendOptions other)
  {
    if (other is null)
    {
      throw new ArgumentNullException(nameof(other));
    }

    MaxMessageSize = other.MaxMessageSize;
    Compression = other.Compression;
  }

  /// <summary>
  ///   The largest message this client will send, in bytes. A larger one ends its call
  ///   <c>RESOURCE_EXHAUSTED</c>, and none of it is sent.
  /// </summary>
  /// <remarks>
  ///   Defaults to none, any message a call is given going out. Zero is refused: it admits only
  ///   empty messages.
  /// </remarks>
  [JsonPropertyName("MaxMessageSize")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public int? MaxMessageSize { get; set; }

  /// <summary>
  ///   The encoding the messages of a call are compressed with, which the call states as
  ///   <c>grpc-encoding</c>. A message that would not be smaller compressed is sent as it is, and
  ///   <c>MaxMessageSize</c> is checked on a message before it is compressed.
  /// </summary>
  /// <remarks>
  ///   The server has to accept the encoding, and says which it accepts in the
  ///   <c>grpc-accept-encoding</c> of its responses. A response that lists encodings without this one
  ///   stops the channel compressing: the calls that start after it send their messages as they
  ///   are, and the channel logs a warning once. A later response that lists it has the channel
  ///   compress again. A call that reached a server which does not accept the encoding ends
  ///   <c>UNIMPLEMENTED</c> and is not sent again.
  ///   Defaults to none, the messages going out as they are, which <c>None</c> says too, over an
  ///   encoding an earlier source set.
  /// </remarks>
  [JsonPropertyName("Compression")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public MessageEncoding? Compression { get; set; }

  /// <summary>Refuses an option outside the range the engine accepts.</summary>
  /// <exception cref="ArgumentOutOfRangeException">An option is outside its stated bounds.</exception>
  public void Validate()
  {
    if (MaxMessageSize is int maxMessageSize && maxMessageSize < 1)
    {
      throw new ArgumentOutOfRangeException(nameof(MaxMessageSize),
                                            maxMessageSize,
                                            "MaxMessageSize has to be at least 1.");
    }

    if (Compression is MessageEncoding compression && !Enum.IsDefined(typeof(MessageEncoding), compression))
    {
      throw new ArgumentOutOfRangeException(nameof(Compression),
                                            compression,
                                            "Compression has to be a name MessageEncoding declares.");
    }
  }
}

/// <summary>How the messages of a call are compressed.</summary>
[JsonConverter(typeof(JsonStringEnumConverter<MessageEncoding>))]
public enum MessageEncoding
{
  /// <summary>RFC 1952 gzip, <c>gzip</c> on the wire.</summary>
  Gzip,

  /// <summary>
  ///   gRPC's <c>deflate</c>: the zlib structure of RFC 1950 around an RFC 1951 stream, and not a raw
  ///   RFC 1951 stream.
  /// </summary>
  Deflate,

  /// <summary>RFC 8878 Zstandard, <c>zstd</c> on the wire.</summary>
  Zstd,

  /// <summary>
  ///   No compression, <c>identity</c> on the wire: the messages go out as they are and no
  ///   <c>grpc-encoding</c> is sent. Stated over an encoding an earlier source set, it turns the
  ///   compression off. It names no encoding to accept, and a list of them refuses it.
  /// </summary>
  None,
}

/// <summary>What a call accepts from the server.</summary>
public sealed class GrpcReceiveOptions
{
  /// <summary>Options nobody has set.</summary>
  public GrpcReceiveOptions()
  {
  }

  /// <summary>A copy of <paramref name="other" />, sharing nothing with it.</summary>
  /// <param name="other">The options to copy.</param>
  /// <exception cref="ArgumentNullException"><paramref name="other" /> is null.</exception>
  public GrpcReceiveOptions(GrpcReceiveOptions other)
  {
    if (other is null)
    {
      throw new ArgumentNullException(nameof(other));
    }

    MaxMessageSize = other.MaxMessageSize;
    Compression = other.Compression is null
                    ? null
                    : new global::System.Collections.Generic.List<MessageEncoding>(other.Compression);
  }

  /// <summary>The largest message this client will accept, in bytes.</summary>
  /// <remarks>
  ///   Defaults to 4194304, 4 MiB. No upper bound, because the largest a caller can name is a
  ///   channel that refuses nothing. Zero is refused: it is a channel that can receive no message
  ///   at all.
  /// </remarks>
  [JsonPropertyName("MaxMessageSize")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public int? MaxMessageSize { get; set; }

  /// <summary>
  ///   The encodings besides <c>identity</c> that this client accepts for the messages of an answer,
  ///   which it states as <c>grpc-accept-encoding</c> in the order given, <c>identity</c> last. A server
  ///   may then compress what it sends, in the first of them that it knows. A name given twice
  ///   counts at its first place. <c>MaxMessageSize</c> bounds a message once it is decompressed. A
  ///   message compressed in an encoding that is not listed ends its call <c>INTERNAL</c>. <c>None</c> is
  ///   refused here: <c>identity</c> is always accepted.
  /// </summary>
  /// <remarks>Defaults to none, only <c>identity</c> being accepted, which an empty list says too.</remarks>
  [JsonPropertyName("Compression")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public global::System.Collections.Generic.List<MessageEncoding>? Compression { get; set; }

  /// <summary>Refuses an option outside the range the engine accepts.</summary>
  /// <exception cref="ArgumentOutOfRangeException">An option is outside its stated bounds.</exception>
  public void Validate()
  {
    if (MaxMessageSize is int maxMessageSize && maxMessageSize < 1)
    {
      throw new ArgumentOutOfRangeException(nameof(MaxMessageSize),
                                            maxMessageSize,
                                            "MaxMessageSize has to be at least 1.");
    }

    if (Compression is { } compression)
    {
      var compressionUndeclared = compression.Where(item => !Enum.IsDefined(typeof(MessageEncoding), item))
                                             .ToList();

      if (compressionUndeclared.Count > 0)
      {
        throw new ArgumentOutOfRangeException(nameof(Compression),
                                              string.Join(", ",
                                                          compressionUndeclared),
                                              "Compression has to be names MessageEncoding declares.");
      }
    }
  }
}

/// <summary>What crosses between the host and the engine on each call, one way and the other.</summary>
public sealed class HostOptions
{
  /// <summary>Options nobody has set.</summary>
  public HostOptions()
  {
  }

  /// <summary>A copy of <paramref name="other" />, sharing nothing with it.</summary>
  /// <param name="other">The options to copy.</param>
  /// <exception cref="ArgumentNullException"><paramref name="other" /> is null.</exception>
  public HostOptions(HostOptions other)
  {
    if (other is null)
    {
      throw new ArgumentNullException(nameof(other));
    }

    Send = other.Send is null
             ? null
             : new HostSendOptions(other.Send);
    Receive = other.Receive is null
                ? null
                : new HostReceiveOptions(other.Receive);
  }

  /// <summary>What the host sends.</summary>
  /// <remarks>Defaults to <c>{}</c>, which leaves each of its options at its own default.</remarks>
  [JsonPropertyName("Send")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public HostSendOptions? Send { get; set; }

  /// <summary>What the engine delivers to the host.</summary>
  /// <remarks>Defaults to <c>{}</c>, which leaves each of its options at its own default.</remarks>
  [JsonPropertyName("Receive")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public HostReceiveOptions? Receive { get; set; }

  /// <summary>Refuses an option outside the range the engine accepts.</summary>
  /// <exception cref="ArgumentOutOfRangeException">An option is outside its stated bounds.</exception>
  public void Validate()
  {
    Send?.Validate();
    Receive?.Validate();
  }
}

/// <summary>What a call's host sends: the messages it hands the engine.</summary>
public sealed class HostSendOptions
{
  /// <summary>Options nobody has set.</summary>
  public HostSendOptions()
  {
  }

  /// <summary>A copy of <paramref name="other" />, sharing nothing with it.</summary>
  /// <param name="other">The options to copy.</param>
  /// <exception cref="ArgumentNullException"><paramref name="other" /> is null.</exception>
  public HostSendOptions(HostSendOptions other)
  {
    if (other is null)
    {
      throw new ArgumentNullException(nameof(other));
    }

    Window = other.Window;
  }

  /// <summary>How many messages a call may have sent and unacquitted at once.</summary>
  /// <remarks>Defaults to 1.</remarks>
  [JsonPropertyName("Window")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public int? Window { get; set; }

  /// <summary>Refuses an option outside the range the engine accepts.</summary>
  /// <exception cref="ArgumentOutOfRangeException">An option is outside its stated bounds.</exception>
  public void Validate()
  {
    if (Window is int window && (window < 1 || window > 536870910))
    {
      throw new ArgumentOutOfRangeException(nameof(Window),
                                            window,
                                            "Window has to be at least 1 and at most 536870910.");
    }
  }
}

/// <summary>What the engine delivers to a call's host: its payloads and its status.</summary>
public sealed class HostReceiveOptions
{
  /// <summary>Options nobody has set.</summary>
  public HostReceiveOptions()
  {
  }

  /// <summary>A copy of <paramref name="other" />, sharing nothing with it.</summary>
  /// <param name="other">The options to copy.</param>
  /// <exception cref="ArgumentNullException"><paramref name="other" /> is null.</exception>
  public HostReceiveOptions(HostReceiveOptions other)
  {
    if (other is null)
    {
      throw new ArgumentNullException(nameof(other));
    }

    Window = other.Window;
    CoalescingBytes = other.CoalescingBytes;
  }

  /// <summary>
  ///   How many of a call's payloads the host may hold at once, delivered and not yet given back.
  ///   The terminal status takes none, so a host holds at most one more.
  /// </summary>
  /// <remarks>Defaults to 4.</remarks>
  [JsonPropertyName("Window")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public int? Window { get; set; }

  /// <summary>
  ///   How many bytes of a response a delivery to the host may wait to gather, so that a unary
  ///   answer's head, message and status reach it in one callback. 0 delivers each read at once.
  /// </summary>
  /// <remarks>Defaults to 16384, 16 KiB.</remarks>
  [JsonPropertyName("CoalescingBytes")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public int? CoalescingBytes { get; set; }

  /// <summary>Refuses an option outside the range the engine accepts.</summary>
  /// <exception cref="ArgumentOutOfRangeException">An option is outside its stated bounds.</exception>
  public void Validate()
  {
    if (Window is int window && (window < 1 || window > 536870910))
    {
      throw new ArgumentOutOfRangeException(nameof(Window),
                                            window,
                                            "Window has to be at least 1 and at most 536870910.");
    }

    if (CoalescingBytes is int coalescingBytes && coalescingBytes < 0)
    {
      throw new ArgumentOutOfRangeException(nameof(CoalescingBytes),
                                            coalescingBytes,
                                            "CoalescingBytes has to be at least 0.");
    }
  }
}
